--
-- Name: workflow_solicitudaprobacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_solicitudaprobacion (
    id bigint NOT NULL,
    tipo character varying(20) NOT NULL,
    objeto_id integer NOT NULL,
    estado character varying(20) NOT NULL,
    comentario_solicitante text NOT NULL,
    comentario_aprobador text NOT NULL,
    fecha_solicitud timestamp with time zone NOT NULL,
    fecha_respuesta timestamp with time zone,
    monto numeric(12,2),
    aprobador_id integer NOT NULL,
    solicitante_id integer NOT NULL,
    CONSTRAINT workflow_solicitudaprobacion_objeto_id_check CHECK ((objeto_id >= 0))
);


